-- 07_dbt_role_user.sql
-- Purpose: Create a dedicated role and service user for dbt (least privilege)
-- dbt can read Bronze and build tables in Silver and Gold only

USE ROLE ACCOUNTADMIN;

-- Role with only the permissions dbt needs
CREATE ROLE IF NOT EXISTS DBT_ROLE;

GRANT USAGE ON WAREHOUSE SNOWFLAKE_LEARNING_WH TO ROLE DBT_ROLE;
GRANT USAGE ON DATABASE OLIST_DB TO ROLE DBT_ROLE;

-- Read-only access to Bronze (current and future tables)
GRANT USAGE ON SCHEMA OLIST_DB.BRONZE TO ROLE DBT_ROLE;
GRANT SELECT ON ALL TABLES IN SCHEMA OLIST_DB.BRONZE TO ROLE DBT_ROLE;
GRANT SELECT ON FUTURE TABLES IN SCHEMA OLIST_DB.BRONZE TO ROLE DBT_ROLE;

-- Full access to build tables and views in Silver and Gold
GRANT ALL ON SCHEMA OLIST_DB.SILVER TO ROLE DBT_ROLE;
GRANT ALL ON SCHEMA OLIST_DB.GOLD TO ROLE DBT_ROLE;

-- Let admins see everything dbt creates
GRANT ROLE DBT_ROLE TO ROLE SYSADMIN;

-- Service user for dbt: key-pair login only, no password, no MFA
CREATE USER IF NOT EXISTS DBT_USER
  TYPE = SERVICE
  DEFAULT_ROLE = DBT_ROLE
  DEFAULT_WAREHOUSE = SNOWFLAKE_LEARNING_WH
  RSA_PUBLIC_KEY = '';

GRANT ROLE DBT_ROLE TO USER DBT_USER;